def preserve_legacy_invoices(apps, schema_editor):
    Invoice = apps.get_model('clinics', 'Invoice')
    InvoiceLineItem = apps.get_model('clinics', 'InvoiceLineItem')
    Payment = apps.get_model('clinics', 'Payment')
    Clinic = apps.get_model('clinics', 'Clinic')
    Patient = apps.get_model('clinics', 'Patient')
    for clinic in Clinic.objects.all():
        clinic.next_invoice_number = 1
        clinic.save(update_fields=['next_invoice_number'])
    for invoice in Invoice.objects.select_related('clinic', 'patient').all():
        invoice.invoice_number = f'LEGACY-{invoice.pk.hex.upper()}'
        invoice.gross_amount_minor = invoice.amount_minor
        invoice.clinic_context = {'name': invoice.clinic.name, 'address': invoice.clinic.address, 'phone': invoice.clinic.phone, 'email': invoice.clinic.email}
        invoice.patient_context = {'name': ' '.join(part for part in (invoice.patient.given_name, invoice.patient.family_name) if part), 'medical_record_number': invoice.patient.medical_record_number, 'date_of_birth': invoice.patient.date_of_birth.isoformat() if invoice.patient.date_of_birth else ''}
        if invoice.examination_id:
            Examination = apps.get_model('clinics', 'Examination')
            exam = Examination.objects.filter(pk=invoice.examination_id).first()
            if exam:
                invoice.patient_context['examination'] = exam.procedure_name
        if invoice.status == 'void':
            invoice.status = 'cancelled'
        elif invoice.status == 'open':
            paid = Payment.objects.filter(invoice_id=invoice.pk, reversed_at__isnull=True).aggregate(total=models.Sum('amount_minor'))['total'] or 0
            invoice.status = 'paid' if paid >= invoice.amount_minor else ('partially_paid' if paid else 'issued')
        if not invoice.issued_at and invoice.status != 'cancelled':
            invoice.issued_at = invoice.created_at
        invoice.save(update_fields=['invoice_number', 'gross_amount_minor', 'clinic_context', 'patient_context', 'status', 'issued_at'])
        InvoiceLineItem.objects.create(clinic_id=invoice.clinic_id, invoice_id=invoice.pk, description='Previously issued service', quantity=1, unit_price_minor=invoice.amount_minor, tax_rate_bps=0, subtotal_minor=invoice.amount_minor, discount_minor=0, tax_minor=0)


